function topicHas(w,id){id=String(id);if(id.startsWith('lv:'))return w.collection!=='slang'&&!w.generalHidden&&!!w.studyRank&&inLevelRange(w.studyRank,Number(id.slice(3)));if(id.startsWith('s:'))return w.collection==='slang'&&(id==='s:trend'?!!(typeof wordTrend==='function'&&wordTrend(w)):w.category==='スラング｜'+id.slice(2));if(id.startsWith('p:'))return isPhrase(w)&&(id==='p:all'||phraseScene(w)===id);return wordTopicIds(w).includes(id)}
function phrasePanel(){if(bankStatus!=='ready')return '';const all=bank.filter(w=>wordInDeck(w,'phrase')),seen=all.filter(w=>wordRec(w.id).seen>0).length,next=topicNextWords('p:all'),ring=typeof progressRing==='function'?progressRing(all.length?seen/all.length:0,seen.toLocaleString(),'フレーズの学習済み'):'';
 return `<section class="x-topic-hub x-phrase-hub" aria-label="フレーズ"><div class="x-topic-hub-main">${topicIcon('p:all','is-large')}<div class="x-topic-hub-text"><h2>定型文・言い回し</h2><p class="x-topic-stat"><b>${seen.toLocaleString()}</b> / ${all.length.toLocaleString()}フレーズ 学習済み</p></div>${ring}</div><div class="x-search x-phrase-search"><span class="x-search-icon" aria-hidden="true">${searchIcon()}</span><input id="phrase-search" class="w-search" type="search" enterkeyhint="search" autocomplete="off" value="${esc(phraseQuery)}" placeholder="フレーズを探す（日本語・タイ語・読み）" oninput="phraseQuery=this.value;wordPage=0;refreshWordList()"></div>${next.length?`<div class="x-topic-actions"><button class="btn x-step-go" onclick="startGuidedStep('p:all')">新しい${next.length}フレーズを覚える →</button></div>`:''}</section>`}
function wordTopics(){return typeof WORD_TOPICS==='undefined'?[]:WORD_TOPICS}
function wordTopicIds(w){return typeof WORD_TOPIC_INDEX==='undefined'?[]:WORD_TOPIC_INDEX[w.id]||[]}
function wordInTopic(w,topic=wordTopic){return !topic||topicHas(w,topic)}
function topicWord(w,topic=wordTopic){if(!topic||w.collection==='slang'||typeof WORD_TOPIC_SENSES==='undefined')return w;const senses=WORD_TOPIC_SENSES[w.id]?.[topic];if(!senses)return w;const meanings=w.meanings.filter(m=>senses.includes(m.sourceSense));return meanings.length?{...w,meanings,ro:meanings[0].ro||w.ro,pos:meanings[0].pos,speechStyle:meanings[0].speechStyle}:w}
function wordTopicLabel(w){const t=wordTopics().find(t=>t.id===wordTopic&&wordTopicIds(w).includes(t.id))||wordTopics().find(t=>t.id===wordTopicIds(w)[0]);return w.collection==='slang'?w.category:t?.label||w.category}
function setWordTopic(topic){if(topic&&!allTopics().some(t=>t.id===topic))return;wordTopic=topic;wordCategory='';wordPos='';wordFrequency='';wordFormality='';wordQuery='';wordPage=0;wordCurrent=null;wordTrail=[];wordSession=null;render()}
