function wordSources(){return `<details class="w-sources"><summary>データについて</summary><p>収録語・訳・用例はAIが作成・点検したもので、ネイティブ話者の確認ではありません。学習範囲は頻度と学習段階をもとにした目安です。</p><p><a href="sources.html" target="_blank" rel="noopener">出典・ライセンス・加工方法 ↗</a>　<a href="origin-review.json" target="_blank" rel="noopener">確認状況 ↗</a>　<a href="word-bank.json" download>語彙データ（CC BY-SA 4.0）↓</a></p></details>`}
let wordQuizMode='th-ja';
