function startWords(kind,onlyIds=null){let pool=onlyIds?onlyIds.map(id=>bankMap.get(id)).filter(Boolean).map(w=>topicWord(w)):selectedWords();if(!pool.length){toast('学習する単語がありません。表示範囲や条件を変えてください。');return}if(kind==='quiz'){const total=pool.length;pool=pool.filter(w=>w.meanings[0].checked);if(!pool.length){toast('この条件にはテストできる語がありません。参考訳は確認が終わるまで出題を控えています。');return}}const selected=onlyIds?pool:pickSessionWords(pool,wordState.dailyGoal);wordSession={kind,topic:wordTopic,mode:wordQuizMode,ids:selected.map(w=>w.id),i:0,revealed:false,answered:null,results:[],choices:kind==='quiz'?makeWordQuestion(selected[0]):[],started:Date.now()};wordCurrent=null;render();window.scrollTo(0,0);autoSpeakSession()}
