function wordSessionView(){const s=wordSession;if(s.i>=s.ids.length){const ok=s.results.filter(x=>x.correct).length,wrong=s.results.filter(x=>!x.correct).map(x=>x.id);return `<div class="w-session"><div class="w-result"><h1>${ok}<small> / ${s.ids.length}</small></h1><h2>${s.kind==='cards'?'思い出せた語':'正解'}</h2><p>${wrong.length?'間違えた語を復習対象にしました。もう一度、意味を思い出してみよう。':'次は日を空けて思い出してみよう。復習時期を記録しました。'}</p>${stepResult(s)}<div class="settings-row">${wrong.length?`<button class="btn" onclick="startWords('${s.kind}',${esc(JSON.stringify(wrong))})">${wrong.length}語をやり直す</button>`:''}<button class="btn light" onclick="exitWordSession()">単語帳へ戻る</button></div></div></div>`}const w=topicWord(bankMap.get(s.ids[s.i]),s.topic),r=wordRec(w.id),answered=s.answered!==null,correct=s.answered===w.id;return `<div class="w-session ${s.kind==='quiz'?'w-quiz-session':''}"><div class="w-session-top"><button class="textbtn" onclick="exitWordSession()">← 終了する</button><span>${s.i+1} / ${s.ids.length} 語</span><span>${s.kind==='cards'?'カード（めくって確認）':s.mode==='listen'?'テスト（聞き取り）':'テスト（4択）'}</span></div><div class="track"><div style="width:${s.i/s.ids.length*100}%"></div></div><section class="w-flashcard ${s.kind==='quiz'?'w-quiz-card':''}">${wordMeta(w)}${s.kind==='cards'||s.mode==='th-ja'?`<div class="w-flash-th" lang="th">${esc(w.th)}</div><div class="w-flash-ro">${esc(w.ro)}</div>${wordAudio(w.id,'音声を聞く')}`:s.mode==='ja-th'?`<h2 class="w-ja-question">${esc(w.meanings[0].ja)}</h2>`:`<div class="w-listen-mark">${icon('audio')}</div>${wordAudio(w.id,'音声を聞く')}<p class="subtext">音を聞いて、いちばん近い意味を選ぼう。</p>`}${s.kind==='cards'?`${s.revealed?`<div class="w-card-answer">${w.meanings.map((m,i)=>`<section class="w-card-sense"><p class="w-card-meaning"><span class="w-card-meaning-no">${i+1}</span>${esc(m.ja)}${wordReference(m)}</p>${m.speechStyle&&!/^標準/.test(m.speechStyle)?`<div class="w-card-style">${esc(styleLabel(m.speechStyle))}</div>`:''}${m.note?`<p class="w-usage-note">${esc(m.note)}</p>`:''}${wordSenseExample(w,m,i)}</section>`).join('')}<div class="w-card-rating"><button class="btn light" onclick="assessCard(false)">もう一度</button><button class="btn" onclick="assessCard(true)">思い出せた</button></div></div>`:`<div class="w-card-rating w-card-reveal"><button class="btn" onclick="revealWordCard()">意味・用例を見る</button></div>`}`:`<div class="w-choices">${s.choices.map(id=>{const x=topicWord(bankMap.get(id),s.topic);return `<button class="option ${answered&&id===w.id?'correct':''} ${answered&&id===s.answered&&!correct?'wrong':''}" ${answered?'disabled':''} onclick="answerWord('${id}')">${s.mode==='ja-th'?`<span lang="th">${esc(x.th)}</span><small>${esc(x.ro)}</small>`:esc(x.meanings[0].ja)}</button>`}).join('')}</div>${answered?`<div class="feedback w-quiz-feedback ${correct?'':'bad'}" role="status"><div class="w-answer-summary"><strong>${correct?'正解！':'正解を確認'}</strong>${wordAudio(w.id,'発音を確認')}</div><div class="w-feedback-term"><span lang="th">${esc(w.th)}</span><b>${esc(w.ro)}</b></div><p>${esc(w.meanings[0].ja)}</p></div><div class="w-quiz-next"><button class="btn" onclick="nextWordQuestion()">${s.i===s.ids.length-1?'結果を見る':'次へ'} ${icon('arrow')}</button></div>`:''}`}</section><div class="w-session-bottom"><button class="btn light x-fav ${r.favorite?'chosen':''}" onclick="favoriteWord('${w.id}')" aria-label="お気に入り${r.favorite?'から外す':'に登録'}" aria-pressed="${r.favorite}" title="お気に入り">${icon('star')}</button><button class="btn light x-rev ${r.manual?'chosen':''}" onclick="reviewWord('${w.id}')" aria-label="復習${r.manual?'から外す':'に登録'}" aria-pressed="${r.manual}" title="復習に登録">${icon('review')}復習</button></div></div>`}

function sanitizeWordState(input){input=input&&typeof input==='object'?input:{};const out=freshWordState();const count=(n,max=Number.MAX_SAFE_INTEGER)=>Number.isFinite(Number(n))?Math.max(0,Math.min(max,Math.floor(Number(n)))):0;{const lv=migrateLevel(input.level);if([0,...WORD_LEVELS.map(([n])=>n)].includes(lv))out.level=lv}if([5,10,20].includes(input.dailyGoal))out.dailyGoal=input.dailyGoal;out.stepWords=count(input.stepWords,100000);if(input.autoplay===false)out.autoplay=false;if([1,2,3].includes(input.stepsPerDay))out.stepsPerDay=input.stepsPerDay;const day=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)?s:'';if(input.today&&typeof input.today==='object')out.today={date:day(input.today.date),steps:count(input.today.steps,99)};if(input.streak&&typeof input.streak==='object')out.streak={last:day(input.streak.last),days:count(input.streak.days,100000)};for(const [id,r]of Object.entries(input.records||{})){if(!/^tl-\d+$/.test(id)||!r||typeof r!=='object')continue;out.records[id]={favorite:!!r.favorite,manual:!!r.manual,stage:count(r.stage,6),seen:count(r.seen),correct:count(r.correct),wrong:count(r.wrong),lapses:count(r.lapses),due:count(r.due),last:count(r.last)}}if(Array.isArray(input.favEx))out.favEx=[...new Set(input.favEx.filter(k=>typeof k==='string'&&/^tl-\d+#\d+$/.test(k)))].slice(0,2000);if(Array.isArray(input.history))out.history=input.history.filter(x=>x&&/^tl-\d+$/.test(x.id)&&['card','test','step'].includes(x.k)).slice(0,400).map(x=>({id:x.id,t:count(x.t),k:x.k,ok:x.ok?1:0}));return out}
function resetWordData(){if(!confirm('単語の学習記録・お気に入り・復習登録をすべて消去します。よろしいですか？'))return;wordState=freshWordState();saveWords();wordCurrent=null;wordSession=null;render();toast('単語の学習記録をリセットしました。')}

function wordRegister(w){return '';return w.collection==='slang'?`<p class="w-register-note">${w.adult?'下ネタ・大人の会話の学習欄です。':'友達の口語・スラングの学習欄です。'}「口語」は話し言葉中心、「スラング」は仲間内の特殊な言い方。粗さは相手との関係・口調でも変わります。</p>`:''}

function wordReference(s){return s.checked?'':`<small class="w-reference" title="追加確認が済むまでテストには出題しません。">${s.reviewStatus==='needs-source'?'要確認':'参考訳'}</small>`}

// Load examples on demand; ordinary word browsing stays compact.
let senseExamples=null,senseExamplesStatus='idle',exampleSenses={};// exampleSenses: which sense a word has inside an example (AI-tagged)
async function loadSenseExamples(){if(['loading','ready'].includes(senseExamplesStatus))return;senseExamplesStatus='loading';try{const rs=await Promise.all([fetch(dataURL('sense-examples.json')),fetch(dataURL('slang-examples.json'))]);if(rs.some(r=>!r.ok))throw Error();const [base,extra]=await Promise.all(rs.map(r=>r.json()));const more=await loadOptionalJSON('more-examples.json',{});exampleSenses=await loadOptionalJSON('example-senses.json',{});if(!base||typeof base!=='object'||!Object.keys(base).length||!more||typeof more!=='object'||Object.values({...base,...more,...extra}).some(e=>!e||!e.th||!e.ja))throw Error();senseExamples={...base,...more,...extra};senseExamplesStatus='ready'}catch{senseExamplesStatus='error'}if(view==='words'&&((wordCurrent&&!wordSession)||(wordSession?.kind==='cards'&&wordSession.revealed)))render()}
// Example sentences split into registered words. A split is shown only when every Thai letter belongs to a
// registered word and the word readings line up with the sentence's own romanization (syllable count and
// initial consonants), so a guess is never shown as fact.
let segBank=null,segIndex=null,segMax=1;const segCache=new Map();
function segEntries(){if(segBank!==bank){segBank=bank;segIndex=new Map();segMax=1;segCache.clear();for(const x of bank){if(x.generalHidden)continue;const cur=segIndex.get(x.th),xs=x.collection==='slang',cs=cur&&cur.collection==='slang';if(!cur||cs&&!xs||cs===xs&&x.frequency>cur.frequency)segIndex.set(x.th,x);if(x.th.length>segMax)segMax=x.th.length}}return segIndex}
const segSyl=r=>foldWord(r).replace(/[.,!?…"“”'‘’()「」:;]/g,' ').split(/\s+/).filter(Boolean),segOnset=x=>x.match(/^[^aeiou]*/)[0];
function segmentSentence(th,ro,prefer=''){const key=th+'\u0001'+ro+'\u0001'+prefer;if(segCache.has(key))return segCache.get(key);const idx=segEntries(),S=segSyl(ro),J=S.length,n=th.length,INF=1e9;
 const cost=Array.from({length:n+1},()=>new Array(J+1).fill(INF)),back=Array.from({length:n+1},()=>new Array(J+1).fill(null));cost[0][0]=0;
 const relax=(i,j,i2,j2,c,step)=>{if(i2>n||j2>J)return;const v=cost[i][j]+c;if(v<cost[i2][j2]){cost[i2][j2]=v;back[i2][j2]={i,j,...step}}};
 for(let i=0;i<n;i++)for(let j=0;j<=J;j++){if(cost[i][j]>=INF)continue;const ch=th[i];
  if(/[\s.,!?…"“”'‘’()「」:;\-]/.test(ch)){relax(i,j,i+1,j,0,{kind:'sep'});continue}
  if(ch==='ๆ'){for(let k=1;k<=3;k++)relax(i,j,i+1,j+k,1,{kind:'rep'});continue}
  if(/[0-9A-Za-z๐-๙]/.test(ch)){let e=i;while(e<n&&/[0-9A-Za-z๐-๙.,]/.test(th[e]))e++;for(let k=1;k<=5;k++)relax(i,j,e,j+k,2,{kind:'other'});continue}
  for(let L=1;L<=segMax&&i+L<=n;L++){const x=idx.get(th.slice(i,i+L));if(!x)continue;const ws=segSyl(x.ro),k=ws.length;if(!k||j+k>J)continue;const ok=ws.every((y,q)=>segOnset(y)===segOnset(S[j+q]));relax(i,j,i+L,j+k,(ok?1:4)-(x.th===prefer?1.1:isPhrase(x)?-3:0),{kind:'word',w:x,aligned:ok})/* a phrase is split into its words unless it is the entry being viewed */}
  relax(i,j,i+1,j,30,{kind:'unknown'})}
 let out=null;if(cost[n][J]<INF){const toks=[];let i=n,j=J;while(i>0||j>0){const b=back[i][j];if(!b)break;toks.push({...b,th:th.slice(b.i,i),ro:S.slice(b.j,j).join(' '),sro:ro});i=b.i;j=b.j}toks.reverse();if(toks.every(t=>t.kind!=='unknown')&&toks.some(t=>t.kind==='word'))out=toks.filter(t=>t.kind!=='sep')}
 segCache.set(key,out);return out}
function segRomaji(t,ro){// the token's own syllables from the sentence romanization keep tones as written there
 const raw=ro.replace(/[.,!?…"“”'‘’()「」:;]/g,' ').split(/\s+/).filter(Boolean);return raw}
// Gloss on a split chip: the viewed headword shows the sense this example belongs to; any other word shows its main sense
// (particles included), preferring a sense that shares kanji with the example's Japanese translation.
function chipGloss(x,ctxJa='',sense=null){const first=t=>String(t).replace(/（[^）]*）/g,'').split(/[・、,，;；/／]/)[0].trim().slice(0,14);if(sense)return first(sense.ja);const ms=x.meanings.filter(m=>!m.isSlang),all=ms.length?ms:x.meanings,hit=ctxJa?all.find(m=>[...m.ja.replace(/（[^）]*）/g,'')].some(c=>/[\u3400-\u9fff]/.test(c)&&ctxJa.includes(c))):null;return first((hit||all[0]).ja)}
function exampleBreakdown(th,ro,prefer='',ctxJa='',sense=null,key=''){const tagged=key&&exampleSenses&&exampleSenses[key]||{};if(key&&exampleSenses&&Object.keys(exampleSenses).length)ctxJa='';/* every example was sense-tagged: untagged words are in their main sense */if(bankStatus!=='ready')return '';const toks=segmentSentence(th,ro,prefer);if(!toks||toks.filter(t=>t.kind==='word').length<2)return '';const raw=segRomaji(null,ro);let pos=0;const nav=!wordSession&&!stepSession;
 const chips=toks.map(t=>{const k=t.kind==='word'?segSyl(t.w.ro).length:t.ro.split(' ').filter(Boolean).length,r=raw.slice(pos,pos+k).join(' ');pos+=k;if(t.kind!=='word')return `<span class="w-seg-chip is-plain"><b lang="th-Latn">${esc(r)}</b><span lang="th">${esc(t.th)}</span></span>`;const x=t.w,gloss=esc(chipGloss(x,ctxJa,sense&&x.th===prefer?sense:tagged[x.th]?x.meanings.find(m=>m.sourceSense===tagged[x.th])||null:null)),inner=`<b lang="th-Latn">${esc(t.aligned?r:x.ro)}</b><span lang="th">${esc(t.th)}</span><small>${gloss}</small>`;return nav?`<button type="button" class="w-seg-chip" onclick="openWord('${x.id}')" aria-label="${esc(x.th)}（${gloss}）を開く">${inner}</button>`:`<button type="button" class="w-seg-chip" data-th="${esc(x.th)}" onclick="speakThaiText(this.dataset.th)" aria-label="${esc(x.th)}（${gloss}）の発音">${inner}</button>`}).join('');
 return `<details class="w-seg"><summary>単語に分解</summary><div class="w-seg-row">${chips}</div><p class="w-seg-note">${nav?'押すとその単語へ移動します（お気に入りは単語のページで）。':'押すと発音します。'}</p></details>`}
// Grammar lessons keep their hand-made word panel; each word that is in the dictionary gets a link to it.
function fillDictLinks(panel){if(!panel)return;const run=()=>{const idx=segEntries();panel.querySelectorAll('.word-item').forEach(it=>{if(it.querySelector('.word-dict'))return;const th=(it.querySelector('.word-th')?.textContent||'').trim(),x=th&&idx.get(th);if(!x||x.collection==='slang')return;const b=document.createElement('button');b.type='button';b.className='textbtn word-dict';b.textContent='辞書で見る →';b.setAttribute('aria-label',th+'を辞書で見る');b.onclick=()=>openDictWord(x.id);(it.querySelector('.word-meaning')||it).appendChild(b)})};if(bankStatus==='ready')run();else loadWordBank().then(()=>{if(bankStatus==='ready')run()})}
function openDictWord(id){keepSearch=false;go('words');openWord(id)}
function wordSenseExample(w,s,i){if(senseExamplesStatus==='idle')loadSenseExamples();if(senseExamplesStatus==='error')return `<div class="w-example"><p>用例を読み込めませんでした。</p><button class="textbtn" onclick="senseExamplesStatus='idle';render()">もう一度読み込む</button></div>`;const e=senseExamples?.[w.id+'#'+s.sourceSense];if(!e)return `<div class="w-example" role="status">用例を読み込んでいます…</div>`;return `<div class="w-example"><div class="w-example-top"><span>用例${e.speechStyle&&!/^標準/.test(e.speechStyle)?` <b class="w-example-style">${esc(e.speechStyle)}</b>`:''}</span><div class="w-example-acts"><button class="w-iconbtn${isFavEx(w.id+'#'+s.sourceSense)?' on':''}" onclick="toggleFavEx('${w.id}#${s.sourceSense}',this)" aria-pressed="${isFavEx(w.id+'#'+s.sourceSense)}" aria-label="${isFavEx(w.id+'#'+s.sourceSense)?'用例をお気に入りから解除':'用例をお気に入りに追加'}">${icon('star')}</button><button class="w-audio" aria-label="意味${i+1}の用例を再生" onclick="playSenseExample('${w.id}',${s.sourceSense},false)" title="用例の発音">${icon('audio')}</button></div></div>${e.context?`<p class="w-example-context">${esc(e.context)}</p>`:''}<p class="w-example-th" lang="th">${esc(e.th)}</p><p class="w-example-ro" lang="th-Latn">${esc(e.ro)}</p><p class="w-example-ja">${esc(e.ja)}${e.checked?'':'<small class="w-reference" title="用例の日本語は未校閲の参考訳です。">参考訳</small>'}</p>${exampleBreakdown(e.th,e.ro,w.th,e.ja,s,w.id+'#'+s.sourceSense)}${e.checked?'':`<details class="w-example-original"><summary>元の英語訳を確認</summary><p>${esc(e.en)}</p></details>`}</div>`}
function playSenseExample(id,n,slow=false){const e=senseExamples?.[id+'#'+n];if(e)speakThaiText(e.speechText||e.th,slow)}
// Guided step session, built on how memory consolidates:
//  1. spaced retrieval — words whose review date has come are tested first (expanding 1→3→7→14→30→60-day gaps);
//  2. encoding with sound and context — each new word is shown with audio, meaning and an example sentence;
//  3. retrieval practice — the new words are then recalled, Thai→Japanese, then Japanese→Thai (both directions);
//  4. within-session relearning — a missed item comes back a few items later until it is answered correctly;
//  5. sleep and spacing — a new word answered right first time is next reviewed tomorrow, a missed one sooner.
let stepSession=null;
const STEP_PHASES={review:'復習',learn:'新しい語',recall:'思い出す',produce:'タイ語で答える'};
function quizzable(w){return w&&w.meanings[0]?.checked}
function startGuidedStep(topic=''){if(bankStatus!=='ready')return;topic=allTopics().some(t=>t.id===topic)&&!SLANG_NO_STEP.has(topic)?topic:'';const tdeck=topic?topicDeck(topic):'general';const news=topic?topicNextWords(topic):nextStepWords();if(senseExamplesStatus==='idle')loadSenseExamples();
 const due=bank.filter(w=>wordInDeck(w,tdeck)&&(!topic||topicHas(w,topic)&&(tdeck!=='general'||wordInLevel(w)))&&dueWord(w)&&quizzable(topicWord(w,topic))&&!news.includes(w)).sort((a,b)=>(wordRec(a.id).due||0)-(wordRec(b.id).due||0)).slice(0,15);
 if(!news.length&&!due.length)return;wordTopic=topic.startsWith('lv:')?'':topic;const q=news.filter(w=>quizzable(topicWord(w,topic))),tasks=[...due.map(w=>({id:w.id,type:'review'})),...news.map(w=>({id:w.id,type:'learn'})),...shuffle(q).map(w=>({id:w.id,type:'recall'})),...shuffle(q).map(w=>({id:w.id,type:'produce'}))];
 stepSession={topic,from:wordState.stepWords,n:stepNumber(),news:news.map(w=>w.id),tasks,i:0,answered:null,choices:null,missed:{},firstReview:{},done:false};prepareStepTask();wordCurrent=null;wordSession=null;render();window.scrollTo(0,0)}
function prepareStepTask(){const s=stepSession,t=s.tasks[s.i];s.answered=null;s.choices=t&&t.type!=='learn'?makeWordQuestion(stepWord(t.id)):null;if(t&&(t.type==='learn'||t.type==='recall'||t.type==='review'))setTimeout(()=>{if(stepSession&&stepSession.tasks[stepSession.i]===t&&wordState.autoplay!==false){const w=bankMap.get(t.id);if(w)speakThaiText(w.speechText||w.th,false,true)}},250)}
function answerStepTask(id){const s=stepSession,t=s.tasks[s.i];if(!t||s.answered!==null)return;s.answered=id;const ok=id===t.id;
 if(t.type==='review'&&!(t.id in s.firstReview)){s.firstReview[t.id]=ok;applyWordResult(t.id,ok)}
 if(!ok){if(t.type!=='review')s.missed[t.id]=true;s.tasks.splice(Math.min(s.i+4,s.tasks.length),0,{...t,retry:true})}
 if((t.type==='produce'||ok)&&wordState.autoplay!==false){const w=bankMap.get(t.id);if(w)speakThaiText(w.speechText||w.th,false,true)}render()}
function nextStepTask(){const s=stepSession;s.i++;if(s.i>=s.tasks.length)finishGuidedStep();else prepareStepTask();render();window.scrollTo(0,0)}
function finishGuidedStep(){const s=stepSession;if(s.done)return;s.done=true;for(const id of s.news)applyWordResult(id,!s.missed[id],Date.now(),'step');if(s.topic){markStudyDay();s.cleared=true}else s.cleared=completeStep({step:{from:s.from,ids:s.news}})}
function stepWord(id){return topicWord(bankMap.get(id),stepSession?.topic||'')}
function exitStepSession(){stepSession=null;render();window.scrollTo(0,0)}
function stepWordFace(w,size=''){return `<div class="g-face ${size}"><span class="g-ro" lang="th-Latn">${esc(w.ro)}</span><span class="g-th" lang="th">${esc(w.th)}</span></div>`}
function stepSessionView(){const s=stepSession,total=s.tasks.length;
 if(s.done){const missed=s.news.filter(id=>s.missed[id]).length,reviewed=Object.keys(s.firstReview).length,reviewOk=Object.values(s.firstReview).filter(Boolean).length;const tp=s.topic&&allTopics().find(x=>x.id===s.topic),more=tp?topicNextWords(tp.id).length>0:nextStepWords().length>0;return `<div class="w-session"><div class="w-result g-result">${tp?`<div class="g-topic-mark">${topicIcon(tp.id,'is-large')}</div><div class="eyebrow">${tp.id.startsWith('lv:')?'学習範囲':'テーマ'}</div><h1>${esc(tp.label)} 完了</h1>`:`<div class="eyebrow">STEP ${s.n}</div><h1>ステップ ${s.n} 完了</h1>`}<ul class="g-summary"><li>新しい語 <b>${s.news.length}</b>語${missed?`（うち ${missed}語は一度間違えたので、早めにもう一度出します）`:'（全部1回目で正解）'}</li>${reviewed?`<li>復習 <b>${reviewOk}</b> / ${reviewed}語 正解</li>`:''}<li>次の復習：${missed?'近いうち':'明日'}</li></ul>${stepsToday()>=wordState.stepsPerDay?'<p class="g-done">✓ 今日の分は完了</p>':''}<div class="settings-row">${more?`<button class="btn${stepsToday()>=wordState.stepsPerDay?' light':''}" onclick="startGuidedStep('${tp?tp.id:''}')">${tp?(tp.id.startsWith('lv:')?'この範囲の続きへ':'このテーマの続きへ'):'次のステップへ'} →</button>`:''}<button class="btn${stepsToday()>=wordState.stepsPerDay?'':' light'}" onclick="exitStepSession()">単語帳へ戻る</button></div></div></div>`}
 const t=s.tasks[s.i],w=stepWord(t.id),answered=s.answered!==null,ok=s.answered===t.id,phase=STEP_PHASES[t.type];
 const head=`<div class="w-session-top"><button class="textbtn" onclick="exitStepSession()">← 中断する</button><span>${s.i+1} / ${total}</span><span class="g-phase g-${t.type}">${phase}${t.retry?' · もう一度':''}</span></div><div class="track"><div style="width:${s.i/total*100}%"></div></div>`;
 if(t.type==='learn'){const ms=w.meanings.filter(m=>!m.isSlang).slice(0,2);return `<div class="w-session">${head}<section class="w-flashcard g-card">${stepWordFace(w,'is-large')}<div class="g-audio">${wordAudio(w.id,'発音')}</div><div class="g-meanings">${ms.map((m,i)=>`<div class="g-meaning"><b>${esc(m.ja)}</b><small>${esc(m.pos)}</small>${wordSenseExample(w,m,i)}</div>`).join('')}</div><div class="w-session-bottom"><button class="btn" onclick="nextStepTask()">覚えた → 次へ</button></div></section></div>`}
 const opts=s.choices.map(id=>stepWord(id)),produce=t.type==='produce';
 return `<div class="w-session w-quiz-session">${head}<section class="w-flashcard w-quiz-card g-card">${produce?`<h2 class="g-prompt">${esc(w.meanings[0].ja)}</h2><p class="g-ask">タイ語では？</p>`:`${stepWordFace(w)}<div class="g-audio">${wordAudio(w.id,'発音')}</div><p class="g-ask">意味は？</p>`}<div class="g-options">${opts.map(o=>`<button class="option g-option ${answered&&o.id===t.id?'correct':''} ${answered&&o.id===s.answered&&!ok?'wrong':''}" ${answered?'disabled':''} onclick="answerStepTask('${o.id}')">${produce?stepWordFace(o,'is-small'):`<span>${esc(o.meanings[0].ja)}</span>`}</button>`).join('')}</div>${answered?`<div class="feedback ${ok?'':'bad'}" role="status"><strong>${ok?'正解！':'惜しい。少しあとでもう一度出します。'}</strong>${produce||!ok?`<br><span class="g-answer">${esc(w.ro)}（${esc(w.th)}）＝ ${esc(w.meanings[0].ja)}</span>`:''}</div><div class="w-session-bottom"><button class="btn" onclick="nextStepTask()">次へ →</button></div>`:''}</section></div>`}
